:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --green: #2ecc71;
  --red: #e74c3c;
  --yellow: #f1c40f;
  --blue: #3498db;
  --accent: #9b59b6;
  --focus: #ffffff;
  --pad-size: clamp(60px, 20vw, 120px);
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 28px 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 480px;
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.status-bar {
  margin-bottom: 20px;
}

.level {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.message {
  min-height: 1.5em;
  font-size: 1rem;
  color: #a0a0b0;
}

.message.game-over {
  color: var(--red);
  font-weight: 700;
}

.pad-grid {
  display: grid;
  grid-template-columns: repeat(2, var(--pad-size));
  gap: var(--gap);
  justify-content: center;
  margin-bottom: 24px;
}

.pad {
  width: var(--pad-size);
  height: var(--pad-size);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, filter 0.1s;
  image-rendering: pixelated;
  outline: none;
}

.pad:focus-visible {
  box-shadow: 0 0 0 3px var(--focus), 0 0 0 6px var(--accent);
}

.pad:hover {
  filter: brightness(1.2);
  transform: scale(1.03);
}

.pad:active,
.pad.active {
  transform: scale(0.95);
  filter: brightness(1.8);
  box-shadow: 0 0 12px currentColor;
}

.pad-green { background: var(--green); color: var(--green); }
.pad-red { background: var(--red); color: var(--red); }
.pad-yellow { background: var(--yellow); color: var(--yellow); }
.pad-blue { background: var(--blue); color: var(--blue); }

.restart-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.1s;
  outline: none;
}

.restart-btn:hover {
  background: #8e44ad;
  transform: scale(1.05);
}

.restart-btn:active {
  transform: scale(0.97);
}

.restart-btn:focus-visible {
  box-shadow: 0 0 0 3px var(--focus), 0 0 0 6px var(--accent);
}

@media (max-width: 400px) {
  .game-card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  :root {
    --gap: 8px;
  }
}

(function() {
  'use strict';

  const pads = [
    document.getElementById('pad0'),
    document.getElementById('pad1'),
    document.getElementById('pad2'),
    document.getElementById('pad3')
  ];
  const levelDisplay = document.getElementById('levelDisplay');
  const message = document.getElementById('message');
  const restartBtn = document.getElementById('restartBtn');

  let sequence = [];
  let playerIndex = 0;
  let level = 0;
  let acceptingInput = false;
  let gameOver = false;
  let playbackTimeout = null;

  function setMessage(text, isGameOver) {
    message.textContent = text;
    if (isGameOver) {
      message.classList.add('game-over');
    } else {
      message.classList.remove('game-over');
    }
  }

  function updateLevel() {
    levelDisplay.textContent = 'Level: ' + level;
  }

  function flashPad(index, duration) {
    const pad = pads[index];
    pad.classList.add('active');
    setTimeout(function() {
      pad.classList.remove('active');
    }, duration);
  }

  function playSequence() {
    acceptingInput = false;
    setMessage('Watch...');
    let i = 0;
    const delay = 600;
    const flashDuration = 350;

    function next() {
      if (i >= sequence.length) {
        acceptingInput = true;
        setMessage('Your turn');
        return;
      }
      flashPad(sequence[i], flashDuration);
      i++;
      playbackTimeout = setTimeout(next, delay);
    }

    playbackTimeout = setTimeout(next, delay);
  }

  function nextRound() {
    level++;
    updateLevel();
    playerIndex = 0;
    sequence.push(Math.floor(Math.random() * 4));
    playSequence();
  }

  function handlePadClick(index) {
    if (!acceptingInput || gameOver) return;

    flashPad(index, 200);

    if (sequence[playerIndex] === index) {
      playerIndex++;
      if (playerIndex === sequence.length) {
        acceptingInput = false;
        setMessage('Good!');
        setTimeout(nextRound, 800);
      }
    } else {
      endGame();
    }
  }

  function endGame() {
    gameOver = true;
    acceptingInput = false;
    clearTimeout(playbackTimeout);
    setMessage('Game over', true);
    restartBtn.textContent = 'Restart';
  }

  function startGame() {
    clearTimeout(playbackTimeout);
    sequence = [];
    playerIndex = 0;
    level = 0;
    gameOver = false;
    acceptingInput = false;
    updateLevel();
    setMessage('Watch...');
    nextRound();
  }

  pads.forEach(function(pad, index) {
    pad.addEventListener('click', function() {
      handlePadClick(index);
    });
  });

  restartBtn.addEventListener('click', startGame);

  startGame();
})();
